   223  mrb_realloc_simple(mrb_state *mrb, void *p,  size_t len)
   224  {
   225    void *p2;
   226
   227    p2 = (mrb->allocf)(mrb, p, len, mrb->allocf_ud);
   228    if (!p2 && len > 0 && mrb->gc.heaps) {
   229      mrb_full_gc(mrb);
   230      p2 = (mrb->allocf)(mrb, p, len, mrb->allocf_ud);
   231    }
   232
   233    return p2;
   234  }
