   236  MRB_API void*
   237  mrb_realloc(mrb_state *mrb, void *p, size_t len)
   238  {
   239    void *p2;
   240
   241    p2 = mrb_realloc_simple(mrb, p, len);
   242    if (len == 0) return p2;
   243    if (p2 == NULL) {
   244      mrb->gc.out_of_memory = TRUE;
   245      mrb_raise_nomemory(mrb);
   246    }
   247    else {
   248      mrb->gc.out_of_memory = FALSE;
   249    }
   250
   251    return p2;
   252  }
